INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(21044, 2104, 'listening', 'Listening Part 4', '<div class="ielts-reading-container">
<h2 class="ielts-reading-question-section-heading">
                                            Questions 31-40                                                                                                                                                
                                                                                                                                    </h2>
                                                                                <div class="ielts-reading-question-section-content">
                                            <div class="ielts-listening-section-content-wrapper"><p>Complete the notes below.</p>
<p>Write ONE WORD ONLY for each answer.</p>
<p><strong>Music therapy for surgical patients</strong></p>
<p><strong>Background</strong></p>
<ul>
<li>Surgery impacts patients because they may experience discomfort or unwelcome changes to their <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">31</strong><input type="text" data-qnum="31" name="question_31" class="ielts-inline-input" placeholder="[31] javob..." autocomplete="off" spellcheck="false"></span></span>.</li>
<li>Current post-surgical strategies focus mainly on pain relief.</li>
</ul>
<p><strong>Recent research</strong></p>
<ul>
